#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#define MAXC 12
#define MAXV 5000
typedef struct {int id;long count;} Result;
void tally(const int votes[],int n,int candidates,long counts[],int *valid,int *invalid){int i;*valid=*invalid=0;for(i=0;i<candidates;i++)counts[i]=0;for(i=0;i<n;i++){int v=votes[i];if(v>=1&&v<=candidates){counts[v-1]++;(*valid)++;}else(*invalid)++;}}
void report(const long counts[],int candidates,int valid,int invalid){Result a[MAXC],temp;int i,j,ties=0;long best=0;for(i=0;i<candidates;i++){a[i].id=i+1;a[i].count=counts[i];}for(i=1;i<candidates;i++){temp=a[i];j=i-1;while(j>=0&&a[j].count<temp.count){a[j+1]=a[j];j--;}a[j+1]=temp;}printf("Valid %d, invalid %d\n",valid,invalid);for(i=0;i<candidates;i++)printf("Candidate %d: %ld votes\n",a[i].id,a[i].count);best=a[0].count;for(i=0;i<candidates;i++)if(a[i].count==best)ties++;if(best==0)puts("No winner (no valid votes)");else if(ties>1)printf("Tie: %d candidates with %ld votes\n",ties,best);else printf("Winner: candidate %d with %ld votes\n",a[0].id,best);}
int main(void){int candidates,n,i,valid,invalid,*votes;long counts[MAXC];clock_t start;int sample[]={1,2,1,2,0,-1,9,3};long temp[MAXC];int v,b;printf("Number of candidates (1-12): ");if(scanf("%d",&candidates)!=1||candidates<1||candidates>MAXC){puts("Invalid candidate count");return 1;}printf("Number of votes (0-5000): ");if(scanf("%d",&n)!=1||n<0||n>MAXV){puts("Invalid vote count");return 1;}votes=(int*)malloc((size_t)(n?n:1)*sizeof(int));if(!votes){puts("Memory error");return 1;}for(i=0;i<n;i++){printf("Vote %d: ",i+1);if(scanf("%d",&votes[i])!=1){puts("Invalid input");free(votes);return 1;}}tally(votes,n,candidates,counts,&valid,&invalid);report(counts,candidates,valid,invalid);puts("\nSmall verification example (3 candidates, includes invalid votes and a tie):");tally(sample,8,3,temp,&v,&b);report(temp,3,v,b);free(votes);start=clock();{int *large=(int*)malloc(500000*sizeof(int));if(large){for(i=0;i<500000;i++)large[i]=(i%13);tally(large,500000,candidates,counts,&valid,&invalid);printf("500000 vote timing: %.6f seconds\n",(double)(clock()-start)/CLOCKS_PER_SEC);free(large);}else puts("500000 vote benchmark skipped: insufficient memory");}return 0;}
